<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use App\Support\Money\Money;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Support\Carbon;

/**
 * Per-user, per-currency balance row. Balances are only changed by WalletService
 * inside a transaction holding a row lock, alongside the matching ledger entries.
 */
/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $user_id
 * @property string $currency
 * @property int $available_amount
 * @property int $escrow_amount
 * @property int $pending_release_amount
 * @property int $reserved_amount
 * @property int $lifetime_earnings_amount
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class Wallet extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'wal';

    protected $fillable = ['user_id', 'currency'];

    protected function casts(): array
    {
        return [
            'available_amount' => 'integer',
            'escrow_amount' => 'integer',
            'pending_release_amount' => 'integer',
            'reserved_amount' => 'integer',
            'lifetime_earnings_amount' => 'integer',
        ];
    }

    /** @return BelongsTo<User, $this> */
    public function user(): BelongsTo
    {
        return $this->belongsTo(User::class);
    }

    /** @return HasMany<LedgerEntry, $this> */
    public function entries(): HasMany
    {
        return $this->hasMany(LedgerEntry::class);
    }

    public function available(): Money
    {
        return Money::of($this->available_amount, $this->currency);
    }

    public function escrow(): Money
    {
        return Money::of($this->escrow_amount, $this->currency);
    }

    public function total(): Money
    {
        return Money::of($this->available_amount + $this->escrow_amount + $this->pending_release_amount, $this->currency);
    }
}
